/* DFS 非递归：两种写法的序列差异 + 连通分量 + 回边计数陷阱 */
#include <stdio.h>
#include <stdlib.h>

#define MAXV 32

typedef struct ArcNode {
    int adjvex;
    struct ArcNode *nextarc;
} ArcNode;

typedef struct {
    char data;
    ArcNode *firstarc;
} VNode;

typedef struct {
    VNode vertices[MAXV];
    int n, e;
} ALGraph;

static void initAL(ALGraph *g, int n)
{
    int i;
    g->n = n;
    g->e = 0;
    for (i = 0; i < n; i++) {
        g->vertices[i].data = (char)('A' + i);
        g->vertices[i].firstarc = NULL;
    }
}

/* 有序插入，保证链上 adjvex 升序 ⇒ 序列可复现 */
static void addEdge(ALGraph *g, int a, int b)
{
    ArcNode **pp, *p;
    pp = &g->vertices[a].firstarc;
    while (*pp != NULL && (*pp)->adjvex < b) { pp = &(*pp)->nextarc; }
    p = (ArcNode *)malloc(sizeof(ArcNode));
    if (p == NULL) { exit(1); }
    p->adjvex = b; p->nextarc = *pp; *pp = p;

    pp = &g->vertices[b].firstarc;
    while (*pp != NULL && (*pp)->adjvex < a) { pp = &(*pp)->nextarc; }
    p = (ArcNode *)malloc(sizeof(ArcNode));
    if (p == NULL) { exit(1); }
    p->adjvex = a; p->nextarc = *pp; *pp = p;

    g->e++;
}

static void destroyAL(ALGraph *g)
{
    int i;
    ArcNode *p, *q;
    for (i = 0; i < g->n; i++) {
        p = g->vertices[i].firstarc;
        while (p != NULL) { q = p->nextarc; free(p); p = q; }
        g->vertices[i].firstarc = NULL;
    }
}

static void printBody(const char *seq, int len)
{
    int i;
    if (len == 0) { printf("(空)"); return; }
    for (i = 0; i < len; i++) {
        if (i > 0) { printf(" "); }
        printf("%c", seq[i]);
    }
}

static int seqEqual(const char *a, int la, const char *b, int lb)
{
    int i;
    if (la != lb) { return 0; }
    for (i = 0; i < la; i++) { if (a[i] != b[i]) { return 0; } }
    return 1;
}

/* 递归版：基准 */
static void dfsRec(const ALGraph *g, int v, int *visited, char *seq, int *len,
                   int depth, int *maxDepth)
{
    ArcNode *p;
    visited[v] = 1;
    seq[(*len)++] = g->vertices[v].data;
    if (depth > *maxDepth) { *maxDepth = depth; }
    for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
        if (!visited[p->adjvex]) {
            dfsRec(g, p->adjvex, visited, seq, len, depth + 1, maxDepth);
        }
    }
}

/* 写法一：弹栈时标记 + 逆序压栈 ⇒ 与递归序列一致 */
static void dfsIterA(const ALGraph *g, int start, int *visited, char *seq, int *len,
                     int *maxStackSize)
{
    int stack[MAXV * MAXV];         /* 允许重复压栈，容量按 2e 上界给足 */
    int nbr[MAXV];
    int top = -1, v, cnt, i;
    ArcNode *p;

    stack[++top] = start;
    if (top + 1 > *maxStackSize) { *maxStackSize = top + 1; }
    while (top >= 0) {
        v = stack[top--];
        if (visited[v]) { continue; }              /* ★ 弹栈后先查标记 */
        visited[v] = 1;
        seq[(*len)++] = g->vertices[v].data;

        cnt = 0;
        for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
            if (!visited[p->adjvex]) { nbr[cnt++] = p->adjvex; }
        }
        for (i = cnt - 1; i >= 0; i--) {           /* ★ 逆序压栈 */
            stack[++top] = nbr[i];
        }
        if (top + 1 > *maxStackSize) { *maxStackSize = top + 1; }
    }
}

/* 写法二：压栈时标记 + 顺序压栈 ⇒ 序列通常与递归版不同 */
static void dfsIterB(const ALGraph *g, int start, int *visited, char *seq, int *len,
                     int *maxStackSize)
{
    int stack[MAXV];
    int top = -1, v, w;
    ArcNode *p;

    visited[start] = 1;
    seq[(*len)++] = g->vertices[start].data;
    stack[++top] = start;
    if (top + 1 > *maxStackSize) { *maxStackSize = top + 1; }
    while (top >= 0) {
        v = stack[top--];
        for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
            w = p->adjvex;
            if (!visited[w]) {
                visited[w] = 1;                    /* ★ 压栈时就标记、就输出 */
                seq[(*len)++] = g->vertices[w].data;
                stack[++top] = w;
            }
        }
        if (top + 1 > *maxStackSize) { *maxStackSize = top + 1; }
    }
}

/* ---------- 连通分量与回边统计 ---------- */
typedef struct {
    int components;
    int treeEdges;
    int naiveBack;      /* 朴素计数：无向图里恰好是真值的 2 倍 */
} DfsStat;

static void dfsComp(const ALGraph *g, int v, int parent, int *visited, DfsStat *st)
{
    ArcNode *p;
    int w;
    visited[v] = 1;
    for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
        w = p->adjvex;
        if (!visited[w]) {
            st->treeEdges++;
            dfsComp(g, w, v, visited, st);
        } else if (w != parent) {
            st->naiveBack++;                       /* ★ 两个端点会各数一次 */
        }
    }
}

int main(void)
{
    static const int E[6][2] = {
        {0,1}, {0,2}, {1,3}, {2,4}, {3,5}, {4,5}
    };
    ALGraph g, gc;
    DfsStat st;
    int visited[MAXV], i, md;
    char sr[MAXV], sa[MAXV], sb[MAXV];
    int lr = 0, la = 0, lb = 0, maxA = 0, maxB = 0;

    printf("== 图：n=6 e=6，边 (0,1)(0,2)(1,3)(2,4)(3,5)(4,5) ==\n");
    initAL(&g, 6);
    for (i = 0; i < 6; i++) { addEdge(&g, E[i][0], E[i][1]); }

    for (i = 0; i < 6; i++) { visited[i] = 0; }
    md = 0;
    dfsRec(&g, 0, visited, sr, &lr, 1, &md);
    printf("  递归 DFS              = ");
    printBody(sr, lr);
    printf(" | 递归最大深度=%d\n", md);

    for (i = 0; i < 6; i++) { visited[i] = 0; }
    dfsIterA(&g, 0, visited, sa, &la, &maxA);
    printf("  非递归A(弹栈标记+逆序压) = ");
    printBody(sa, la);
    printf(" | 显式栈峰值=%d 与递归一致=%d\n", maxA, seqEqual(sr, lr, sa, la));

    for (i = 0; i < 6; i++) { visited[i] = 0; }
    dfsIterB(&g, 0, visited, sb, &lb, &maxB);
    printf("  非递归B(压栈标记+顺序压) = ");
    printBody(sb, lb);
    printf(" | 显式栈峰值=%d 与递归一致=%d\n", maxB, seqEqual(sr, lr, sb, lb));

    printf("  三种写法访问的顶点集合相同（长度都是 %d/%d/%d）= %d\n",
           lr, la, lb, (lr == la && la == lb));
    printf("  递归深度 %d vs 显式栈峰值 %d/%d：显式栈存的是待探索的兄弟，不是递归路径\n",
           md, maxA, maxB);

    /* ---------- 连通分量与回边计数 ---------- */
    printf("\n== 非连通图：n=8，边 (0,1)(1,2)(2,0)(3,4)(5,6)，顶点 7 孤立 ==\n");
    initAL(&gc, 8);
    addEdge(&gc, 0, 1);
    addEdge(&gc, 1, 2);
    addEdge(&gc, 2, 0);
    addEdge(&gc, 3, 4);
    addEdge(&gc, 5, 6);
    printf("  n=%d e=%d\n", gc.n, gc.e);

    for (i = 0; i < 8; i++) { visited[i] = 0; }
    st.components = 0;
    st.treeEdges  = 0;
    st.naiveBack  = 0;
    for (i = 0; i < 8; i++) {
        if (!visited[i]) {
            st.components++;
            dfsComp(&gc, i, -1, visited, &st);
        }
    }
    printf("  连通分量个数 k=%d\n", st.components);
    printf("  生成森林树边数=%d  验证 树边数 == n-k (%d-%d=%d) ? %d\n",
           st.treeEdges, gc.n, st.components, gc.n - st.components,
           st.treeEdges == gc.n - st.components);
    printf("  真回边数 = e - 树边数 = %d - %d = %d\n",
           gc.e, st.treeEdges, gc.e - st.treeEdges);
    printf("  朴素计数（已访问且非父结点就 +1）= %d\n", st.naiveBack);
    printf("  朴素计数 == 2 × 真值 ? %d（无向图每条回边被两个端点各数一次）\n",
           st.naiveBack == 2 * (gc.e - st.treeEdges));
    printf("  朴素计数 / 2 = %d  与真值相符 = %d\n",
           st.naiveBack / 2, st.naiveBack / 2 == gc.e - st.treeEdges);
    printf("  有环（真回边数 > 0）? %d\n", gc.e - st.treeEdges > 0);

    destroyAL(&g);
    destroyAL(&gc);
    printf("\n两张邻接表已释放\n");
    return 0;
}

/* BFS：层次扩散、无权最短路径、入队标记时机、Floyd 交叉验证 */
#include <stdio.h>
#include <stdlib.h>

#define MAXV 32
#define INF  32767

typedef struct ArcNode {
    int adjvex;
    struct ArcNode *nextarc;
} ArcNode;

typedef struct {
    char data;
    ArcNode *firstarc;
} VNode;

typedef struct {
    VNode vertices[MAXV];
    int n, e;
} ALGraph;

static void initAL(ALGraph *g, int n)
{
    int i;
    g->n = n;
    g->e = 0;
    for (i = 0; i < n; i++) {
        g->vertices[i].data = (char)('A' + i);
        g->vertices[i].firstarc = NULL;
    }
}

static void insertSorted(ArcNode **head, int v)
{
    ArcNode **pp = head;
    ArcNode *p;
    while (*pp != NULL && (*pp)->adjvex < v) { pp = &(*pp)->nextarc; }
    p = (ArcNode *)malloc(sizeof(ArcNode));
    if (p == NULL) { exit(1); }
    p->adjvex = v; p->nextarc = *pp; *pp = p;
}

static void addEdge(ALGraph *g, int a, int b)
{
    insertSorted(&g->vertices[a].firstarc, b);
    insertSorted(&g->vertices[b].firstarc, a);
    g->e++;
}

static void destroyAL(ALGraph *g)
{
    int i;
    ArcNode *p, *q;
    for (i = 0; i < g->n; i++) {
        p = g->vertices[i].firstarc;
        while (p != NULL) { q = p->nextarc; free(p); p = q; }
        g->vertices[i].firstarc = NULL;
    }
}

static void printBody(const char *seq, int len)
{
    int i;
    if (len == 0) { printf("(空)"); return; }
    for (i = 0; i < len; i++) {
        if (i > 0) { printf(" "); }
        printf("%c", seq[i]);
    }
}

static int seqEqual(const char *a, int la, const char *b, int lb)
{
    int i;
    if (la != lb) { return 0; }
    for (i = 0; i < la; i++) { if (a[i] != b[i]) { return 0; } }
    return 1;
}

/* 正确写法：入队时就标记 */
static void bfs(const ALGraph *g, int start, int *visited, int *dist,
                char *seq, int *len, long *enq, long *deq)
{
    int queue[MAXV];
    int front = 0, rear = 0, v, w;
    ArcNode *p;

    visited[start] = 1;
    dist[start]    = 0;
    queue[rear++]  = start;
    (*enq)++;

    while (front < rear) {
        v = queue[front++];
        (*deq)++;
        seq[(*len)++] = g->vertices[v].data;
        for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
            w = p->adjvex;
            if (!visited[w]) {
                visited[w]   = 1;
                dist[w]      = dist[v] + 1;
                queue[rear++] = w;
                (*enq)++;
            }
        }
    }
}

/* 错误写法：出队时才标记（结果对，但重复入队） */
static void bfsBuggy(const ALGraph *g, int start, int *visited,
                     char *seq, int *len, long *enq, long *deq)
{
    int queue[MAXV * MAXV];          /* 容量必须放大，否则重复入队会越界 */
    int front = 0, rear = 0, v, w;
    ArcNode *p;

    queue[rear++] = start;
    (*enq)++;
    while (front < rear) {
        v = queue[front++];
        (*deq)++;
        if (visited[v]) { continue; }
        visited[v] = 1;
        seq[(*len)++] = g->vertices[v].data;
        for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
            w = p->adjvex;
            if (!visited[w]) {
                queue[rear++] = w;
                (*enq)++;
            }
        }
    }
}

/* 逐层打印，同时给出每层的层号（= 最短距离） */
static void bfsLevels(const ALGraph *g, int start, int *visited, int *dist,
                      int *maxLevel, int *maxWidth)
{
    int queue[MAXV];
    int front = 0, rear = 0, level = 0, i, levelSize, v, w;
    ArcNode *p;

    visited[start] = 1;
    dist[start]    = 0;
    queue[rear++]  = start;
    *maxLevel = 0;
    *maxWidth = 0;

    while (front < rear) {
        levelSize = rear - front;              /* ★ 必须在出队之前取 */
        if (levelSize > *maxWidth) { *maxWidth = levelSize; }
        printf("    第%d层(距离%d, %d个): ", level, level, levelSize);
        for (i = 0; i < levelSize; i++) {
            v = queue[front++];
            if (i > 0) { printf(" "); }
            printf("%c", g->vertices[v].data);
            for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
                w = p->adjvex;
                if (!visited[w]) {
                    visited[w]   = 1;
                    dist[w]      = level + 1;
                    queue[rear++] = w;
                }
            }
        }
        printf("\n");
        level++;
    }
    *maxLevel = level;
}

/* DFS 树深度：用来对照「DFS 深度 != 最短距离」 */
static void dfsDepth(const ALGraph *g, int v, int *visited, int *depth, int d)
{
    ArcNode *p;
    visited[v] = 1;
    depth[v]   = d;
    for (p = g->vertices[v].firstarc; p != NULL; p = p->nextarc) {
        if (!visited[p->adjvex]) {
            dfsDepth(g, p->adjvex, visited, depth, d + 1);
        }
    }
}

/* Floyd-Warshall 求全源最少边数，作为 BFS 结果的独立交叉验证 */
static void floydHops(const ALGraph *g, int d[][MAXV])
{
    int i, j, k;
    ArcNode *p;
    for (i = 0; i < g->n; i++) {
        for (j = 0; j < g->n; j++) { d[i][j] = (i == j) ? 0 : INF; }
    }
    for (i = 0; i < g->n; i++) {
        for (p = g->vertices[i].firstarc; p != NULL; p = p->nextarc) {
            d[i][p->adjvex] = 1;
        }
    }
    for (k = 0; k < g->n; k++) {
        for (i = 0; i < g->n; i++) {
            for (j = 0; j < g->n; j++) {
                /* ★ 先判 INF 再相加，否则 INF+INF 会溢出成负数 */
                if (d[i][k] < INF && d[k][j] < INF &&
                    d[i][k] + d[k][j] < d[i][j]) {
                    d[i][j] = d[i][k] + d[k][j];
                }
            }
        }
    }
}

int main(void)
{
    static const int E[6][2] = {
        {0,1}, {0,2}, {1,3}, {2,4}, {3,5}, {4,5}
    };
    ALGraph g, k5;
    int visited[MAXV], dist[MAXV], ddepth[MAXV], hop[MAXV][MAXV];
    char seq[MAXV];
    int i, j, len, maxLevel, maxWidth, diff, allSame;
    long enq, deq;

    printf("== 图：n=6 e=6，边 (0,1)(0,2)(1,3)(2,4)(3,5)(4,5) ==\n");
    initAL(&g, 6);
    for (i = 0; i < 6; i++) { addEdge(&g, E[i][0], E[i][1]); }

    /* ① 逐层 BFS */
    printf("  从 A 出发的逐层 BFS：\n");
    for (i = 0; i < 6; i++) { visited[i] = 0; dist[i] = -1; }
    bfsLevels(&g, 0, visited, dist, &maxLevel, &maxWidth);
    printf("  层数(=树的深度+1)=%d  最大层宽 w=%d\n", maxLevel, maxWidth);

    /* ② 普通 BFS 拿序列 */
    for (i = 0; i < 6; i++) { visited[i] = 0; dist[i] = -1; }
    len = 0; enq = 0; deq = 0;
    bfs(&g, 0, visited, dist, seq, &len, &enq, &deq);
    printf("  BFS 序列 = ");
    printBody(seq, len);
    printf("\n");
    printf("  入队 %ld 次 出队 %ld 次（正确写法：每个顶点各一次，= n = %d）\n",
           enq, deq, g.n);

    /* ③ 错误写法：出队时才标记 */
    {
        char seq2[MAXV];
        int len2 = 0;
        long enq2 = 0, deq2 = 0;
        for (i = 0; i < 6; i++) { visited[i] = 0; }
        bfsBuggy(&g, 0, visited, seq2, &len2, &enq2, &deq2);
        printf("  错误写法（出队才标记）：入队 %ld 次 出队 %ld 次 序列长度 %d\n",
               enq2, deq2, len2);
        printf("  序列仍然正确 = %d，但多入队 %ld 次\n",
               seqEqual(seq, len, seq2, len2), enq2 - enq);
    }

    /* ④ DFS 深度 vs BFS 距离 */
    for (i = 0; i < 6; i++) { visited[i] = 0; ddepth[i] = -1; }
    dfsDepth(&g, 0, visited, ddepth, 0);
    printf("\n  顶点  BFS距离  DFS树深度  是否相同\n");
    diff = 0;
    for (i = 0; i < 6; i++) {
        int same = (dist[i] == ddepth[i]);
        if (!same) { diff++; }
        printf("    %c      %d        %d        %d\n",
               g.vertices[i].data, dist[i], ddepth[i], same);
    }
    printf("  不一致的顶点有 %d 个 → DFS 深度不能当最短距离用\n", diff);

    /* ⑤ Floyd 交叉验证 BFS 距离 */
    floydHops(&g, hop);
    allSame = 1;
    for (i = 0; i < 6; i++) { if (hop[0][i] != dist[i]) { allSame = 0; } }
    printf("  Floyd 全源最少边数（第 0 行）: ");
    for (i = 0; i < 6; i++) {
        if (i > 0) { printf(" "); }
        printf("%d", hop[0][i]);
    }
    printf("\n");
    printf("  与 BFS 的 dist 完全一致 = %d\n", allSame);
    printf("  全源距离矩阵：\n");
    for (i = 0; i < 6; i++) {
        printf("    v%d:", i);
        for (j = 0; j < 6; j++) { printf(" %d", hop[i][j]); }
        printf("\n");
    }

    /* ⑥ K5 上放大「出队才标记」的代价 */
    printf("\n== 完全图 K5：n=5 e=10 ==\n");
    initAL(&k5, 5);
    for (i = 0; i < 5; i++) {
        for (j = i + 1; j < 5; j++) { addEdge(&k5, i, j); }
    }
    printf("  n=%d e=%d\n", k5.n, k5.e);
    for (i = 0; i < 5; i++) { visited[i] = 0; dist[i] = -1; }
    len = 0; enq = 0; deq = 0;
    bfs(&k5, 0, visited, dist, seq, &len, &enq, &deq);
    printf("  正确写法：入队 %ld 次 出队 %ld 次 序列 = ", enq, deq);
    printBody(seq, len);
    printf("  各点距离 = ");
    for (i = 0; i < 5; i++) {
        if (i > 0) { printf(" "); }
        printf("%d", dist[i]);
    }
    printf("\n");
    {
        char seq2[MAXV];
        int len2 = 0;
        long enq2 = 0, deq2 = 0;
        for (i = 0; i < 5; i++) { visited[i] = 0; }
        bfsBuggy(&k5, 0, visited, seq2, &len2, &enq2, &deq2);
        printf("  错误写法：入队 %ld 次 出队 %ld 次（放大 %.1f 倍）\n",
               enq2, deq2, (double)enq2 / (double)enq);
    }

    destroyAL(&g);
    destroyAL(&k5);
    printf("\n两张邻接表已释放\n");
    return 0;
}

#include <stdio.h>

#define MAXV 32
#define INF  32767

/* 邻接矩阵存网：edges[i][j] = 权值，无边 = INF，对角线 = 0 */
typedef struct {
    int edges[MAXV][MAXV];
    int n, e;
} MGraph;

static void init(MGraph *g, int n)
{
    int i, j;

    g->n = n;
    g->e = 0;
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            g->edges[i][j] = (i == j) ? 0 : INF;
}

static void addEdge(MGraph *g, int u, int v, int w)
{
    g->edges[u][v] = w;
    g->edges[v][u] = w;      /* 无向网：对称填 */
    g->e++;
}

/* Prim：返回 MST 总权值，-1 表示图不连通。
   closeEdge[v] = v 靠哪个 U 中顶点连进来，mstU[i] = 第 i+1 个并入 U 的顶点 */
static int prim(const MGraph *g, int start, int *closeEdge, int *mstU, int verbose)
{
    int lowcost[MAXV];
    int i, j, k, min, total = 0;

    for (j = 0; j < g->n; j++) {
        lowcost[j] = g->edges[start][j];
        closeEdge[j] = start;
    }
    lowcost[start] = 0;                  /* start 第一个进 U */

    for (i = 1; i < g->n; i++) {         /* 还要选 n-1 个顶点 */
        min = INF;
        k = -1;
        for (j = 0; j < g->n; j++)       /* 扫全部 n 个 → O(n^2) 的来源 */
            if (lowcost[j] != 0 && lowcost[j] < min) {
                min = lowcost[j];
                k = j;
            }
        if (k == -1) return -1;          /* ★ 图不连通，必须显式失败 */

        mstU[i - 1] = k;
        total += min;
        lowcost[k] = 0;                  /* k 并入 U */

        for (j = 0; j < g->n; j++)       /* 用 k 更新 V-U 中各点 */
            if (lowcost[j] != 0 && g->edges[k][j] < lowcost[j]) {
                lowcost[j] = g->edges[k][j];
                closeEdge[j] = k;
            }

        if (verbose) {                   /* 快照放在更新之后，才看得见 lowcost 被 k 改小 */
            printf("    第%d步：选中 v%d（lowcost=%d，经 v%d）→ 边 (%d,%d) 权 %d，累计 %d\n",
                   i, k, min, closeEdge[k], closeEdge[k], k, min, total);
            printf("           更新后 lowcost: ");
            for (j = 0; j < g->n; j++) {
                if (lowcost[j] == 0) printf("U");
                else if (lowcost[j] >= INF) printf("-");
                else printf("%d", lowcost[j]);
                printf(" ");
            }
            printf("（U=已入集合，-=INF 不可达）\n");
        }
    }
    return total;
}

static void printMst(const MGraph *g, int start, const int *closeEdge)
{
    int v, sum = 0, cnt = 0;

    for (v = 0; v < g->n; v++) {
        if (v == start) continue;
        printf("    MST 边 (%d,%d) 权 %d\n", closeEdge[v], v,
               g->edges[closeEdge[v]][v]);
        sum += g->edges[closeEdge[v]][v];
        cnt++;
    }
    printf("    边数 = %d（应为 n-1 = %d）相符 = %d，权值和 = %d\n",
           cnt, g->n - 1, cnt == g->n - 1, sum);
}

/* 把无向边编码成一个可比较的整数，便于比较两个边集是否相同 */
static int edgeKey(int u, int v)
{
    int a = (u < v) ? u : v;
    int b = (u < v) ? v : u;

    return a * MAXV + b;
}

/* ---------- 只用于交叉验证的极简 Kruskal（详见下一张卡） ---------- */
typedef struct { int u, v, w; } Edge;

static int ufP[MAXV];

static int ufFind(int x)
{
    while (ufP[x] != x) x = ufP[x];
    return x;
}

static int kruskal(Edge *es, int m, int n, int *considered, int *skipped)
{
    int i, j, cnt = 0, total = 0;
    Edge t;

    for (i = 1; i < m; i++) {            /* 插入排序：稳定，同权值保持输入次序 */
        t = es[i];
        j = i - 1;
        while (j >= 0 && es[j].w > t.w) { es[j + 1] = es[j]; j--; }
        es[j + 1] = t;
    }
    for (i = 0; i < n; i++) ufP[i] = i;

    *considered = 0;
    *skipped = 0;
    for (i = 0; i < m && cnt < n - 1; i++) {
        int ru = ufFind(es[i].u), rv = ufFind(es[i].v);

        (*considered)++;
        if (ru != rv) { ufP[rv] = ru; cnt++; total += es[i].w; }
        else (*skipped)++;
    }
    return (cnt == n - 1) ? total : -1;
}

int main(void)
{
    MGraph g;
    Edge es[16];
    int closeEdge[MAXV], mstU[MAXV], considered, skipped;
    int t0, t1, tk;
    int i;
    static const int EU[10] = { 0, 0, 0, 1, 1, 2, 2, 2, 3, 4 };
    static const int EV[10] = { 1, 2, 3, 2, 4, 3, 4, 5, 5, 5 };
    static const int EW[10] = { 6, 1, 5, 5, 3, 5, 6, 4, 2, 6 };

    init(&g, 6);
    for (i = 0; i < 10; i++) {
        addEdge(&g, EU[i], EV[i], EW[i]);
        es[i].u = EU[i]; es[i].v = EV[i]; es[i].w = EW[i];
    }
    printf("== 连通网：n=6 e=10 ==\n");
    for (i = 0; i < 10; i++)
        printf("  边 (%d,%d) 权 %d\n", EU[i], EV[i], EW[i]);

    printf("\n== Prim 从 v0 出发（逐步追踪）==\n");
    t0 = prim(&g, 0, closeEdge, mstU, 1);
    printf("  总权值 = %d\n", t0);
    printf("  顶点并入 U 的次序：v0");
    for (i = 0; i < g.n - 1; i++) printf(" → v%d", mstU[i]);
    printf("\n");
    printMst(&g, 0, closeEdge);

    printf("\n== Prim 从 v1 出发（不追踪）==\n");
    t1 = prim(&g, 1, closeEdge, mstU, 0);
    printf("  总权值 = %d，与从 v0 出发相同 = %d\n", t1, t1 == t0);
    printf("  顶点并入 U 的次序：v1");
    for (i = 0; i < g.n - 1; i++) printf(" → v%d", mstU[i]);
    printf("\n");
    printMst(&g, 1, closeEdge);

    printf("\n== Kruskal 交叉验证 ==\n");
    tk = kruskal(es, 10, 6, &considered, &skipped);
    printf("  总权值 = %d，与 Prim 相同 = %d\n", tk, tk == t0);
    printf("  考虑 %d 条边、选 %d 条、跳 %d 条、提前 break 省掉 %d 条检查\n",
           considered, g.n - 1, skipped, 10 - considered);
    printf("  排序后次序：");
    for (i = 0; i < 10; i++) printf("(%d,%d)%d ", es[i].u, es[i].v, es[i].w);
    printf("\n");

    /* ── MST 不唯一的演示：三角形三条边权都是 1 ── */
    {
        MGraph tri;
        int ce0[MAXV], ce1[MAXV], mu[MAXV], tot0, tot1, same, t;
        int k0[2], k1[2];

        init(&tri, 3);
        addEdge(&tri, 0, 1, 1);
        addEdge(&tri, 0, 2, 1);
        addEdge(&tri, 1, 2, 1);

        printf("\n== 三角形 n=3，三条边权都是 1（MST 不唯一）==\n");
        tot0 = prim(&tri, 0, ce0, mu, 0);
        printf("  从 v0：边集 {(%d,%d),(%d,%d)} 总权值 %d\n",
               ce0[1], 1, ce0[2], 2, tot0);
        tot1 = prim(&tri, 1, ce1, mu, 0);
        printf("  从 v1：边集 {(%d,%d),(%d,%d)} 总权值 %d\n",
               ce1[0], 0, ce1[2], 2, tot1);

        /* 规范化后再比较两个边集：从 v0 得到 {(ce0[1],1),(ce0[2],2)}，
           从 v1 得到 {(ce1[0],0),(ce1[2],2)}，端点次序不同但边是无向的 */
        k0[0] = edgeKey(ce0[1], 1);
        k0[1] = edgeKey(ce0[2], 2);
        k1[0] = edgeKey(ce1[0], 0);
        k1[1] = edgeKey(ce1[2], 2);
        if (k0[0] > k0[1]) { t = k0[0]; k0[0] = k0[1]; k0[1] = t; }
        if (k1[0] > k1[1]) { t = k1[0]; k1[0] = k1[1]; k1[1] = t; }
        same = (k0[0] == k1[0] && k0[1] == k1[1]);
        printf("  两次边集是否完全相同 = %d，总权值是否相同 = %d\n",
               same, tot0 == tot1);
    }

    /* ── 不连通图：Prim 必须显式失败 ── */
    {
        MGraph bad;
        int ce[MAXV], mu[MAXV], r;

        init(&bad, 4);
        addEdge(&bad, 0, 1, 1);
        addEdge(&bad, 2, 3, 1);

        printf("\n== 不连通图 n=4，边 (0,1) 与 (2,3) ==\n");
        r = prim(&bad, 0, ce, mu, 0);
        printf("  prim 返回 %d（-1 = 正确识别出图不连通）\n", r);
    }

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>

#define MAXV 32
#define MAXE 64

/* ================= 并查集：三种实现 ================= */

/* ① 朴素：不压缩、不按秩，只把 rb 挂到 ra 下 */
static int pPlain[MAXV];

static int findPlain(const int *parent, int x, int *steps)
{
    while (parent[x] != x) { x = parent[x]; (*steps)++; }
    return x;
}

/* ② 带路径压缩 */
static int pPC[MAXV];

static int findPC(int *parent, int x, int *steps)
{
    if (parent[x] == x) return x;
    (*steps)++;
    parent[x] = findPC(parent, parent[x], steps);   /* 递归回来直接挂到根 */
    return parent[x];
}

/* ③ 带按秩合并（配合路径压缩用） */
static int pRank[MAXV], rRank[MAXV];

static int findRank(int x)
{
    while (pRank[x] != x) x = pRank[x];
    return x;
}

static void unionRank(int a, int b)
{
    int ra = findRank(a), rb = findRank(b);
    int t;

    if (ra == rb) return;
    if (rRank[ra] < rRank[rb]) { t = ra; ra = rb; rb = t; }   /* 矮的挂到高的下 */
    pRank[rb] = ra;
    if (rRank[ra] == rRank[rb]) rRank[ra]++;
}

/* 建链实验：依次 union(i, i-1)，朴素写法会长成 n-1 的链 */
static void buildChain(int *parent, int n)
{
    int i;

    for (i = 0; i < n; i++) parent[i] = i;
    for (i = 1; i < n; i++) parent[i - 1] = i;   /* 等价于朴素 union(i, i-1) */
}

static int depthOf(const int *parent, int x)
{
    int d = 0;

    while (parent[x] != x) { x = parent[x]; d++; }
    return d;
}

/* ================= Kruskal ================= */

typedef struct { int u, v, w; } Edge;

static int ufP[MAXV];

static int ufFind(int x)
{
    while (ufP[x] != x) x = ufP[x];
    return x;
}

static int kruskal(Edge *es, int m, int n, int *considered, int *skipped, int *outU, int *outV, int *outW)
{
    int i, j, cnt = 0, total = 0;
    Edge t;

    for (i = 1; i < m; i++) {            /* 插入排序：稳定，同权值保持输入次序 */
        t = es[i];
        j = i - 1;
        while (j >= 0 && es[j].w > t.w) { es[j + 1] = es[j]; j--; }
        es[j + 1] = t;
    }
    for (i = 0; i < n; i++) ufP[i] = i;

    *considered = 0;
    *skipped = 0;
    for (i = 0; i < m && cnt < n - 1; i++) {
        int ru = ufFind(es[i].u), rv = ufFind(es[i].v);

        (*considered)++;
        if (ru != rv) {
            ufP[rv] = ru;
            outU[cnt] = es[i].u; outV[cnt] = es[i].v; outW[cnt] = es[i].w;
            cnt++;
            total += es[i].w;
            printf("    选 (%d,%d) 权 %d → 累计 %d（已选 %d 条）\n",
                   es[i].u, es[i].v, es[i].w, total, cnt);
        } else {
            (*skipped)++;
            printf("    跳 (%d,%d) 权 %d → %d 与 %d 已在同一分量（会成环）\n",
                   es[i].u, es[i].v, es[i].w, es[i].u, es[i].v);
        }
    }
    return (cnt == n - 1) ? total : -1;
}

int main(void)
{
    Edge es[16];
    int outU[8], outV[8], outW[8], considered, skipped;
    int tk, i;
    static const int EU[10] = { 0, 0, 0, 1, 1, 2, 2, 2, 3, 4 };
    static const int EV[10] = { 1, 2, 3, 2, 4, 3, 4, 5, 5, 5 };
    static const int EW[10] = { 6, 1, 5, 5, 3, 5, 6, 4, 2, 6 };

    for (i = 0; i < 10; i++) { es[i].u = EU[i]; es[i].v = EV[i]; es[i].w = EW[i]; }

    printf("== Kruskal：n=6 e=10（与 Prim 同一张网）==\n");
    printf("  输入次序：");
    for (i = 0; i < 10; i++) printf("(%d,%d)%d ", EU[i], EV[i], EW[i]);
    printf("\n");
    tk = kruskal(es, 10, 6, &considered, &skipped, outU, outV, outW);
    printf("  排序后：");
    for (i = 0; i < 10; i++) printf("(%d,%d)%d ", es[i].u, es[i].v, es[i].w);
    printf("\n");
    printf("  总权值 = %d（Prim 从任何起点也是 15）\n", tk);
    printf("  考虑 %d 条、选 %d 条、跳 %d 条、提前 break 省掉 %d 条检查\n",
           considered, 6 - 1, skipped, 10 - considered);
    printf("  MST 边集：");
    for (i = 0; i < 5; i++) printf("(%d,%d)%d ", outU[i], outV[i], outW[i]);
    printf("\n");

    /* ── 不连通图 ── */
    {
        Edge bad[4];
        int cu, cs, bu[4], bv[4], bw[4], rb;

        bad[0].u = 0; bad[0].v = 1; bad[0].w = 1;
        bad[1].u = 2; bad[1].v = 3; bad[1].w = 1;
        printf("\n== 不连通图 n=4，边 (0,1) 与 (2,3) ==\n");
        rb = kruskal(bad, 2, 4, &cu, &cs, bu, bv, bw);
        printf("  返回 %d（-1 = 正确识别出图不连通），考虑 %d 条、跳 %d 条，只选出 %d 条 < n-1 = 3\n",
               rb, cu, cs, cu - cs);
    }

    /* ── union 必须先 find ── */
    {
        int wrong[4], right[4];
        int w2, w3, r2, r3, ra, rb;
        int dummy = 0;

        printf("\n== 「union 必须先 find」的反例：n=4，合并次序 (0,1)(2,3)(1,3) ==\n");
        for (i = 0; i < 4; i++) { wrong[i] = i; right[i] = i; }

        /* 错误写法：parent[b] = parent[a]，没有先 find 拿到根 */
        wrong[1] = wrong[0];           /* union(0,1)：0 恰好是根，侥幸正确 */
        wrong[3] = wrong[2];           /* union(2,3)：2 恰好是根，侥幸正确 */
        wrong[3] = wrong[1];           /* union(1,3)：1 已不是根！3 被挂到 0 上 */
        w2 = findPlain(wrong, 2, &dummy);
        w3 = findPlain(wrong, 3, &dummy);

        /* 正确写法：每次都先 find 拿到两个根，再合并 */
        ra = findPlain(right, 0, &dummy);
        rb = findPlain(right, 1, &dummy);
        if (ra != rb) right[rb] = ra;              /* union(0,1) */
        ra = findPlain(right, 2, &dummy);
        rb = findPlain(right, 3, &dummy);
        if (ra != rb) right[rb] = ra;              /* union(2,3) */
        ra = findPlain(right, 1, &dummy);
        rb = findPlain(right, 3, &dummy);
        if (ra != rb) right[rb] = ra;              /* union(1,3)：先 find 再挂 */
        r2 = findPlain(right, 2, &dummy);
        r3 = findPlain(right, 3, &dummy);

        printf("  错误写法 parent[] = %d %d %d %d\n",
               wrong[0], wrong[1], wrong[2], wrong[3]);
        printf("    find(2)=%d find(3)=%d 相同? %d\n", w2, w3, w2 == w3);
        printf("  正确写法 parent[] = %d %d %d %d\n",
               right[0], right[1], right[2], right[3]);
        printf("    find(2)=%d find(3)=%d 相同? %d\n", r2, r3, r2 == r3);
        printf("  （2 与 3 之间有一条边，本该连通 → 错误写法判成不连通）\n");
    }

    /* ── 路径压缩与按秩合并的收益 ── */
    {
        int n = 8, rounds = 3, x, k, d;
        int stepsPlain, stepsPC, totalPlain = 0, totalPC = 0;
        int perRoundP[4], perRoundC[4];
        int maxPlain = 0, maxRank = 0;

        printf("\n== 并查集优化收益：n=8，依次 union(i, i-1) ==\n");
        buildChain(pPlain, n);                      /* 朴素写法：长成长度 n-1 的链 */
        for (x = 0; x < n; x++) pPC[x] = pPlain[x]; /* 同样的链，但带路径压缩 */
        for (x = 0; x < n; x++) { pRank[x] = x; rRank[x] = 0; }
        for (x = 1; x < n; x++) unionRank(x, x - 1);/* 按秩写法：长成一棵星形树 */

        for (x = 0; x < n; x++) {
            d = depthOf(pPlain, x);
            if (d > maxPlain) maxPlain = d;
            d = depthOf(pRank, x);
            if (d > maxRank) maxRank = d;
        }
        printf("  朴素 union 后各顶点深度 = ");
        for (x = 0; x < n; x++) printf("%d ", depthOf(pPlain, x));
        printf("最深 %d（一条链）\n", maxPlain);
        printf("  按秩 union 后各顶点深度 = ");
        for (x = 0; x < n; x++) printf("%d ", depthOf(pRank, x));
        printf("最深 %d（一棵星形树）\n", maxRank);

        for (k = 0; k < rounds; k++) {
            stepsPlain = 0;
            stepsPC = 0;
            for (x = 0; x < n; x++) {
                findPlain(pPlain, x, &stepsPlain);
                findPC(pPC, x, &stepsPC);
            }
            perRoundP[k] = stepsPlain;
            perRoundC[k] = stepsPC;
            totalPlain += stepsPlain;
            totalPC += stepsPC;
        }
        printf("  连续 %d 轮「查询全部 %d 个顶点」，每轮走动的 parent 指针步数：\n",
               rounds, n);
        for (k = 0; k < rounds; k++)
            printf("    第%d轮：朴素 %d 步，路径压缩 %d 步\n",
                   k + 1, perRoundP[k], perRoundC[k]);
        printf("  合计：朴素 %d 步，路径压缩 %d 步，压缩后少走 %d 步\n",
               totalPlain, totalPC, totalPlain - totalPC);
    }

    printf("\n演示结束\n");
    return 0;
}
